// Quiz classique tout prêt (cedric, 22/10 : « des questions traditionnelles, écrites, 4 réponses écrites et un visuel de
// la réponse ») : par thème et par niveau, à côté du Juste Chiffre tout prêt (banque-chiffres.js). La bonne réponse est
// écrite en premier ; elles sont mélangées quand la question entre dans un quiz.
// Trois niveaux sans chevauchement (cedric, 22/10) : Facile (5 à 8 ans), Moyen (9 à 11 ans, le plus fourni : « charge à
// mort les questions moyennes »), Difficile (12 à 15 ans).
// L'image de la révélation (la TV ne la montre qu'à la révélation, jamais pendant la question) : au niveau Facile, un
// émoji ou une vraie photo ; aux niveaux Moyen et Difficile, une vraie photo seulement, jamais d'émoji. [recherche] :
// les mots (en anglais) pour trouver cette photo libre de droits (scripts/banque-photos.mjs) ; la photo choisie vit
// dans web/public/banque-quiz/<id>.jpg. Émojis d'Android 9 au plus (Mi Box) : pas de 🪐, 🫁, 🧊, 🟢…
// Faits simples et sûrs, propositions courtes. Données pures, testées.
import { NIVEAUX_CHIFFRES, QUESTIONS_CHIFFRES, THEMES_CHIFFRES } from "./banque-chiffres.js";
import { PHOTOS_QUIZ } from "./banque-quiz/liste.js";

const AVEC_PHOTO = new Set(PHOTOS_QUIZ);

/** Thèmes des questions toutes prêtes : ceux du Juste Chiffre, plus ceux des seules questions à 4 réponses. */
export const THEMES_TOUT_PRETS = {
  ...THEMES_CHIFFRES, cuisine: "Cuisine et aliments", pays: "Pays et villes", histoire: "Histoire et mythologie",
  transports: "Transports", metiers: "Métiers", sciences: "Sciences",
};

const slug = (t) => `${t}`.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 72);
const EMOJI = /^(\p{Extended_Pictographic}|\p{Regional_Indicator})/u;
/**
 * [illustration] : « 🐘 elephant » (émoji puis recherche de la photo), « 🎨 » (émoji seul) ou « elephant » (photo seule).
 * [photo] : la photo choisie, si elle est sur le site ; elle passe avant l'émoji.
 */
const q = (theme, niveau, illustration, text, ...choices) => {
  const [ageMin, ageMax] = NIVEAUX_CHIFFRES[niveau];
  const [tete, ...reste] = illustration.split(" ");
  const emoji = EMOJI.test(tete) ? tete : null;
  const recherche = (emoji ? reste : [tete, ...reste]).join(" ").trim();
  const id = `qc-${slug(text)}`;
  return {
    id, theme, niveau, ageMin, ageMax, text, choices, correct: 0, ...(emoji ? { emoji } : {}), ...(recherche ? { recherche } : {}),
    ...(AVEC_PHOTO.has(id) ? { photo: `banque-quiz/${id}.jpg` } : {}),
  };
};

